function Assert-EnvelopeAdmissionFaultBoundary([string]$Workspace,[string]$AdmissionId,[string]$UnitId,[string]$Fault){
  $transactionId="$AdmissionId-admitted-transition";$intentPath=Join-Path $Workspace "receipts\transactions\$transactionId.intent.json";$completionPath=Join-Path $Workspace "receipts\transactions\$transactionId.completion.json";$stagePath=Join-Path $Workspace "receipts\transactions\$transactionId.artifact-0.pending";$artifactPath=Join-Path $Workspace "receipts\$AdmissionId.json";$unitPath=Join-Path $Workspace "iteration-units\$UnitId.json";$intent=Read-MorphospaceProtocolJson $intentPath;$stateHash=Get-MorphospaceCanonicalJsonSha256 (Read-MorphospaceProtocolJson (Join-Path $Workspace 'workspace.state.json'));$eventsPath=Join-Path $Workspace 'iteration-events.jsonl';$events=@(Get-Content -LiteralPath $eventsPath|Where-Object{$_}|ForEach-Object{$_|ConvertFrom-Json});$eventCount=@($events|Where-Object{[string]$_.event_id-ceq"$AdmissionId-admitted"}).Count;$ledger=Get-EnvelopeTransitionLedgerModule;$eventPlaced=&$ledger {param($path,$ownedIntent,$required)if($required){return [bool](Assert-MorphospaceLedgerEventPlacement $path $ownedIntent -RequirePresent)};return [bool](Assert-MorphospaceLedgerEventPlacement $path $ownedIntent)} $eventsPath $intent ($Fault-ceq'after-event')
  Assert-Envelope (-not(Test-Path -LiteralPath $completionPath)) "admission interruption '$Fault' published a completion"
  if($Fault-ceq'after-intent'){Assert-Envelope ($stateHash-ceq[string]$intent.pre.state.sha256-and(Test-Path -LiteralPath $stagePath)-and(Get-MorphospaceFileSha256 $stagePath)-ceq[string]$intent.artifacts[0].sha256-and-not(Test-Path -LiteralPath $artifactPath)-and-not(Test-Path -LiteralPath $unitPath)-and-not$eventPlaced-and$eventCount-eq0) "admission interruption '$Fault' did not preserve the exact pre-projection boundary";return}
  $artifactExact=(Test-Path -LiteralPath $artifactPath)-and(Get-MorphospaceFileSha256 $artifactPath)-ceq[string]$intent.artifacts[0].sha256-and-not(Test-Path -LiteralPath $stagePath)
  if($Fault-ceq'after-state'){Assert-Envelope ($stateHash-ceq[string]$intent.target.state.sha256-and$artifactExact-and-not(Test-Path -LiteralPath $unitPath)-and-not$eventPlaced-and$eventCount-eq0) "admission interruption '$Fault' did not preserve the exact state-projected boundary";return}
  $unitExact=(Test-Path -LiteralPath $unitPath)-and(Get-MorphospaceCanonicalJsonSha256 (Read-MorphospaceProtocolJson $unitPath))-ceq[string]$intent.target.unit.sha256
  Assert-Envelope ($Fault-ceq'after-event'-and$stateHash-ceq[string]$intent.target.state.sha256-and$artifactExact-and$unitExact-and$eventPlaced-and$eventCount-eq1) "admission interruption '$Fault' did not preserve the exact event-appended boundary"
}
function Invoke-EnvelopeRetirementFault([string]$Workspace,[string]$OutPath,[string]$Fault,[string]$Timestamp){
  $automationPath=Join-Path $PSScriptRoot 'WorkUnitAutomation.psm1';$automation=@(Get-Module -All|Where-Object{$_.Path-eq$automationPath}|Select-Object -Last 1)[0];if($null-eq$automation){$automation=Import-Module $automationPath -Force -PassThru}
  $dryArguments=@{Action='RetireProposed';WorkspaceRoot=$Workspace;UnitId='u002';ReplacementUnitId='u003';RetirementReason='contract-invalid';OutPath=$OutPath;Timestamp=$Timestamp}
  $dry=&$automation {param($arguments)Invoke-MorphospaceWorkUnitAutomation @arguments} $dryArguments;$pre=$dry.proposed_retirement.authenticated_preimage
  $executeArguments=$dryArguments.Clone();$executeArguments.ExpectedStateSha256=[string]$pre.state_sha256;$executeArguments.ExpectedUnitSha256=[string]$pre.unit_sha256;$executeArguments.ExpectedUnitRawSha256=[string]$pre.unit_raw_sha256;$executeArguments.ExpectedEventsSha256=[string]$pre.events_sha256;$executeArguments.ExpectedEventsLength=[long]$pre.events_length;$executeArguments.ExpectedEventTailId=[string]$pre.event_tail_id;$executeArguments.ExpectedProposedRetirementBindingSha256=[string]$dry.proposed_retirement.binding_sha256;$executeArguments.TransitionFaultAfter=$Fault;$executeArguments.Execute=$true
  $interrupted=$false;try{&$automation {param($arguments)Invoke-MorphospaceWorkUnitAutomation @arguments} $executeArguments|Out-Null}catch{$interrupted=$_.Exception.Message-like'*Injected interruption*'}
  if(-not$interrupted){throw "RetireProposed fault '$Fault' did not interrupt at its intended boundary."}
  $intentFiles=@(Get-ChildItem -LiteralPath (Join-Path $Workspace 'receipts\transactions') -Filter 'u002-proposal-retired-*-transition.intent.json')
  if($intentFiles.Count-ne1){throw "RetireProposed fault '$Fault' did not leave exactly one owned transition intent."}
  [pscustomobject]@{dry=$dry;pre=$pre;transaction_id=$intentFiles[0].Name.Substring(0,$intentFiles[0].Name.Length-'.intent.json'.Length)}
}
